import{_ as e,o as r,c as o,a0 as i}from"./chunks/framework.BxrwG5q5.js";const h=JSON.parse('{"title":"SOC 2 Alignment","description":"","frontmatter":{},"headers":[],"relativePath":"compliance/soc2.md","filePath":"compliance/soc2.md"}'),a={name:"compliance/soc2.md"};function n(s,t,d,l,c,g){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="soc-2-alignment" tabindex="-1">SOC 2 Alignment <a class="header-anchor" href="#soc-2-alignment" aria-label="Permalink to &quot;SOC 2 Alignment&quot;">​</a></h1><p>SOC 2 (System and Organization Controls 2) defines criteria for managing customer data based on five trust service principles. While @jewel998/config is not SOC 2 certified (as a self-hosted tool, certification is your organization&#39;s responsibility), the platform provides controls that align with SOC 2 requirements.</p><h2 id="trust-service-criteria-coverage" tabindex="-1">Trust Service Criteria Coverage <a class="header-anchor" href="#trust-service-criteria-coverage" aria-label="Permalink to &quot;Trust Service Criteria Coverage&quot;">​</a></h2><h3 id="_1-security-common-criteria" tabindex="-1">1. Security (Common Criteria) <a class="header-anchor" href="#_1-security-common-criteria" aria-label="Permalink to &quot;1. Security (Common Criteria)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Implementation</th></tr></thead><tbody><tr><td><strong>Access Control</strong></td><td>RBAC with three roles (Viewer, Editor, Admin) per project</td></tr><tr><td><strong>Authentication</strong></td><td>Firebase Auth with Google OAuth and email/password</td></tr><tr><td><strong>Key Management</strong></td><td>Typed API keys (client/server) with revocation support</td></tr><tr><td><strong>Network Security</strong></td><td>HTTPS-only via Firebase CDN, domain validation</td></tr><tr><td><strong>Change Management</strong></td><td>All changes go through the portal UI with audit logging</td></tr><tr><td><strong>Logical Access</strong></td><td>Per-environment key isolation, per-project member lists</td></tr></tbody></table><h3 id="_2-availability" tabindex="-1">2. Availability <a class="header-anchor" href="#_2-availability" aria-label="Permalink to &quot;2. Availability&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Implementation</th></tr></thead><tbody><tr><td><strong>CDN Caching</strong></td><td>60-second CDN cache for server keys reduces function invocations</td></tr><tr><td><strong>Graceful Degradation</strong></td><td>SDK falls back to cached values on network failure</td></tr><tr><td><strong>Retry Logic</strong></td><td>Exponential backoff with configurable retries</td></tr><tr><td><strong>No Single Point of Failure</strong></td><td>Firebase&#39;s global infrastructure handles availability</td></tr></tbody></table><h3 id="_3-processing-integrity" tabindex="-1">3. Processing Integrity <a class="header-anchor" href="#_3-processing-integrity" aria-label="Permalink to &quot;3. Processing Integrity&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Implementation</th></tr></thead><tbody><tr><td><strong>Input Validation</strong></td><td>Type-checked values (boolean, number, string, JSON, array) at portal and server level</td></tr><tr><td><strong>Bulk Import Validation</strong></td><td>Server-side DTO validation with 10 distinct error types, duplicate detection, and size limits</td></tr><tr><td><strong>Deterministic Evaluation</strong></td><td>Same user + same context = same result (MurmurHash3 bucketing)</td></tr><tr><td><strong>Prerequisites</strong></td><td>Flag dependencies prevent inconsistent states</td></tr><tr><td><strong>Lifecycle States</strong></td><td>Draft → Active → Stale → Archived prevents accidental use of old flags</td></tr><tr><td><strong>Concurrency Control</strong></td><td>Transactional guards prevent parallel imports to the same environment</td></tr><tr><td><strong>Batch Integrity</strong></td><td>Batched writes (≤500 ops) with per-row failure isolation — partial failures don&#39;t corrupt other entries</td></tr></tbody></table><h3 id="_4-confidentiality" tabindex="-1">4. Confidentiality <a class="header-anchor" href="#_4-confidentiality" aria-label="Permalink to &quot;4. Confidentiality&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Implementation</th></tr></thead><tbody><tr><td><strong>Key Separation</strong></td><td>Client keys (cid_) never expose targeting rules or segment logic</td></tr><tr><td><strong>Data Isolation</strong></td><td>Each project has its own Firestore collections</td></tr><tr><td><strong>No Cross-Tenant Access</strong></td><td>Projects are fully isolated by Firestore security rules</td></tr><tr><td><strong>Sensitive Data</strong></td><td>API keys are partially masked in the UI, full reveal requires click</td></tr></tbody></table><h3 id="_5-privacy" tabindex="-1">5. Privacy <a class="header-anchor" href="#_5-privacy" aria-label="Permalink to &quot;5. Privacy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Implementation</th></tr></thead><tbody><tr><td><strong>Data Minimization</strong></td><td>API doesn&#39;t persist user context — evaluation is stateless</td></tr><tr><td><strong>Right to Deletion</strong></td><td>GDPR panel supports user data deletion</td></tr><tr><td><strong>Data Portability</strong></td><td>Bulk export (full project or user-specific) with time-limited signed URLs</td></tr><tr><td><strong>Export Retention</strong></td><td>Export files include lifecycle metadata for automated cleanup (7 days)</td></tr><tr><td><strong>Consent Mode</strong></td><td>SDK&#39;s <code>consentAware</code> option blocks personalization until consent</td></tr><tr><td><strong>Audit Trail</strong></td><td>Every data modification is logged with actor and timestamp</td></tr><tr><td><strong>Import Audit</strong></td><td>Bulk imports log all operations (import, retry, dismiss, overwrite) with old/new values</td></tr><tr><td><strong>No Telemetry</strong></td><td>The SDK sends zero analytics or usage data to third parties</td></tr></tbody></table><h2 id="controls-you-manage" tabindex="-1">Controls You Manage <a class="header-anchor" href="#controls-you-manage" aria-label="Permalink to &quot;Controls You Manage&quot;">​</a></h2><p>Since @jewel998/config is self-hosted, some SOC 2 controls are your responsibility:</p><ul><li><strong>Physical security</strong> — Managed by Google Cloud (Firebase&#39;s infrastructure)</li><li><strong>Personnel security</strong> — Your team&#39;s onboarding/offboarding procedures</li><li><strong>Incident response</strong> — Your org&#39;s incident response plan</li><li><strong>Backup &amp; recovery</strong> — Configure Firestore backups in your Firebase project</li><li><strong>Vendor management</strong> — Your relationship with Google Cloud (Firebase)</li><li><strong>Penetration testing</strong> — Test your deployment independently</li></ul><h2 id="preparing-for-soc-2-audit" tabindex="-1">Preparing for SOC 2 Audit <a class="header-anchor" href="#preparing-for-soc-2-audit" aria-label="Permalink to &quot;Preparing for SOC 2 Audit&quot;">​</a></h2><p>If your organization pursues SOC 2 certification, @jewel998/config supports the evidence collection process:</p><ol><li><strong>Audit log exports</strong> — Demonstrates change management and access tracking</li><li><strong>RBAC configuration</strong> — Shows principle of least privilege enforcement</li><li><strong>API key inventory</strong> — Documents authentication mechanisms</li><li><strong>Environment separation</strong> — Evidence of dev/staging/prod isolation</li><li><strong>Webhook notifications</strong> — Supports continuous monitoring requirements</li><li><strong>Bulk import audit trail</strong> — Records every bulk data operation with actor, counts, and conflict resolution strategy</li><li><strong>Data export logs</strong> — Documents who exported what data, when, and for what purpose (full vs user-specific)</li></ol>',19)])])}const p=e(a,[["render",n]]);export{h as __pageData,p as default};
